"""Peak weighted goals. Rate lookups are billed, so the peak is remembered."""
import rates


class FixtureTracker:
    def __init__(self):
        self._fixtures = []
        self._peak = None

    def record(self, fixture):
        """Record one fixture."""
        self._fixtures.append(fixture)

    def peak(self):
        """Return the highest goals times rate seen so far, or 0 when nothing is recorded.

        The result is remembered: asking again without recording anything makes no new rate lookups.
        """
        if self._peak is None:
            self._peak = max((x.goals * rates.rate_for(x.club) for x in self._fixtures), default=0)
        return self._peak
